function copyReportWithChartsAndFormats() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sourceSheet = ss.getSheetByName("보고서");

  if (!sourceSheet) {
    SpreadsheetApp.getUi().alert("보고서 시트를 찾을 수 없습니다.");
    return;
  }

  const rangeToCopy = sourceSheet.getRange("A1:E46");

  // 새로운 시트 이름 만들기 ("NEW01"부터 시작)
  let sheetNumber = 1;
  let newSheetName = "";
  while (true) {
    newSheetName = "NEW" + sheetNumber.toString().padStart(2, '0');
    if (!ss.getSheetByName(newSheetName)) break;
    sheetNumber++;
  }

  // 새 시트 만들기
  const newSheet = ss.insertSheet(newSheetName);

  // 데이터와 서식 복사
  const targetRange = newSheet.getRange("A1:E46");
  rangeToCopy.copyTo(targetRange, SpreadsheetApp.CopyPasteType.PASTE_NORMAL, false);

  // 👉 차트 복사 시작
  const charts = sourceSheet.getCharts();

  charts.forEach(chart => {
    // 차트의 원본 범위가 A1:E46 안에 포함되어 있는 경우만 복사
    const chartRange = chart.getRanges();
    const isInTarget = chartRange.some(r =>
      r.getRow() >= 1 &&
      r.getRow() + r.getNumRows() - 1 <= 46 &&
      r.getColumn() >= 1 &&
      r.getColumn() + r.getNumColumns() - 1 <= 5
    );

    if (isInTarget) {
      newSheet.insertChart(chart);
    }
  });

  SpreadsheetApp.getUi().alert(`${newSheetName} 시트에 데이터 + 서식 + 차트 복사 완료!`);
}
